(277513,30835,'ua','Очевидно, вона ріже акуратно, але вчора ... криві квадрати.'::text,'Очевидно, вона ріже акуратно, але вчора нарізала криві квадрати.'::text,'Очевидно, вона ріже акуратно, але вчора вона ... криві квадрати.'::text,'Очевидно, вона ріже акуратно, але вчора вона нарізала криві квадрати.'::text),
(277756,30862,'ua','Зазвичай вона їздить сама, але вчора ... з друзями.'::text,'Зазвичай вона їздить сама, але вчора їхала з друзями.'::text,'Зазвичай вона їздить сама, але вчора вона ... з друзями.'::text,'Зазвичай вона їздить сама, але вчора вона їхала з друзями.'::text),
(278512,30946,'ua','Чекай, вона казала, що вони зазвичай грають, але сьогодні ввечері ... танцювальну вечірку.'::text,'Чекай, вона казала, що вони зазвичай грають, але сьогодні ввечері влаштовують танцювальну вечірку.'::text,'Чекай, вона казала, що вони зазвичай грають, але сьогодні ввечері вони ... танцювальну вечірку.'::text,'Чекай, вона казала, що вони зазвичай грають, але сьогодні ввечері вони влаштовують танцювальну вечірку.'::text),
(282886,31432,'ua','Зазвичай вона носить сіре, але вчора ... щось геть інше, бро.'::text,'Зазвичай вона носить сіре, але вчора вдягла щось геть інше, бро.'::text,'Зазвичай вона носить сіре, але вчора вона ... щось геть інше, бро.'::text,'Зазвичай вона носить сіре, але вчора вона вдягла щось геть інше, бро.'::text),
(284848,31650,'ua','Бездоганно: зазвичай він їсть із миски, а тепер ... картон.'::text,'Бездоганно: зазвичай він їсть із миски, а тепер їсть картон.'::text,'Бездоганно: зазвичай він їсть із миски, а тепер він ... картон.'::text,'Бездоганно: зазвичай він їсть із миски, а тепер він їсть картон.'::text),
(285676,31742,'ua','Вони стрибнули крізь двері, ... хотіли летіти вічно!'::text,'Вони стрибнули крізь двері, бо хотіли летіти вічно!'::text,'Вони стрибнули крізь двері, ... вони хотіли летіти вічно!'::text,'Вони стрибнули крізь двері, бо вони хотіли летіти вічно!'::text),
(293398,32600,'ua','Вона стрибає зі сходів, а її тато обіцяє, що ... її.'::text,'Вона стрибає зі сходів, а її тато обіцяє, що зловить її.'::text,'Вона стрибає зі сходів, а її тато обіцяє, що він ... її.'::text,'Вона стрибає зі сходів, а її тато обіцяє, що він зловить її.'::text),
(293416,32602,'ua','Він губить свої тюльпани й каже: Обіцяю, що ... обережнішим.'::text,'Він губить свої тюльпани й каже: Обіцяю, що буду обережнішим.'::text,'Він губить свої тюльпани й каже: Я обіцяю, що ... обережнішим.'::text,'Він губить свої тюльпани й каже: Я обіцяю, що буду обережнішим.'::text)
) v(id, eid, lang, n_intro_text, n_full_sentence, o_intro_text, o_full_sentence)
